export const lessonContentById = Object.fromEntries(
  Object.entries(courses).map(([id, content]) => [
    id,
    {
      ...content,
      blocks: content.sections.flatMap(([heading, text]) => [
        { type: "h2", text: heading },
        { type: "p", text },
      ]),
      viz: [],
    },
  ])
)

export const getLessonContent = (id, catalogEntry) => {
  const content = lessonContentById[id]
  if (!content || !catalogEntry) return null

  return {
    ...catalogEntry,
    ...content,
  }
}
